package com.yeyamo_mobile.api.feed_service.domain;import static org.junit.jupiter.api.Assertions.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import com.yeyamo_mobile.api.feed_service.application.ranking.PersonalizedRankingStrategy;import com.yeyamo_mobile.api.feed_service.domain.model.*;
class FeedDomainTests{@Test void metricsNeverBecomeNegative(){UUID id=UUID.randomUUID();FeedMetric m=FeedMetric.empty(id).adjust(-1,-1,-1,-1);assertEquals(0,m.likes());assertEquals(0,m.comments());}
 @Test void rankingRewardsFreshnessEngagementAndAffinity(){Instant now=Instant.now();FeedPost p=new FeedPost(UUID.randomUUID(),"author",null,"PUBLIC","PUBLISHED",null,List.of(),List.of(),now.minus(Duration.ofHours(1)),now);var strategy=new PersonalizedRankingStrategy();double basic=strategy.score(new FeedCandidate(p,FeedMetric.empty(p.postId())),Map.of(),now);double personalized=strategy.score(new FeedCandidate(p,new FeedMetric(p.postId(),10,3,2,1,now)),Map.of("author",5d),now);assertTrue(personalized>basic);}}
